def strategy(history, rng):
    if not history:
        return 'C'
    n = len(history)
    my = [h[0] for h in history]
    op = [h[1] for h in history]

    opD = op.count('D')
    myD = my.count('D')

    if n < 4:
        if opD == 0:
            return 'C'
        if opD == n:
            return 'D'
        return 'C'

    if n >= 2:
        if my[-1] == 'D' and op[-1] == 'D' and my[-2] == 'D' and op[-2] == 'D':
            return 'C'

    recent_op = op[-6:]
    recent_opD = recent_op.count('D')

    if n >= 95:
        if opD * 2 < n:
            return 'D'
        return 'C' if op[-1] == 'C' and recent_opD <= 1 else 'D'

    if op[-1] == 'D':
        if op[-2] == 'D' and op[-3] == 'D':
            return 'D'
        if n >= 6 and recent_opD >= 3:
            return 'D'
        return 'D'

    if recent_opD >= 4:
        return 'D'

    if opD >= 4 and n >= 8 and myD > opD + 2:
        return 'C'

    if opD == 1 and n >= 6:
        return 'C'

    if n >= 8 and opD * 4 < n:
        if n % 11 == 0 and n < 90:
            return 'D'
        return 'C'

    if opD * 2 > n:
        if op[-1] == 'C' and op[-2] == 'C':
            return 'C'
        return 'D'

    return 'C'
